from ..data_layer.msg_faraday_mode import FaradayModeInterface
from ..data_layer.msg_dsp_mode import DspModeInterface
from ..data_layer.msg_service import ServiceInterface

from ..utils import intlify


class BasicsPublicInterface(object):

    def __init__(self, connection):
        self.connection = connection

    def get_faraday_mode(self, board, cpu, humanize=True):
        """
        Get mode of a selected CPU.

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get DSP Mode    0x12    0x31    humanize=${False}
            -> 9

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get Faraday Mode    0x12    0x31
            -> [mode_09]NyquistCommonChannelDeviceNormal

        """
        board, cpu = intlify(board, cpu)
        _, _, mode = FaradayModeInterface(self.connection).get_faraday_mode(board, cpu, humanize)
        return mode

    def get_dsp_mode(self, board, cpu, humanize=True):
        """
        Get mode of a selected CPU.

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get DSP Mode    0x12    0x31    humanize=${False}
            -> 9

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get DSP Mode    0x12    0x31
            -> [mode_09]NyquistCommonChannelDeviceNormal

        """
        board, cpu = intlify(board, cpu)
        _, _, mode = DspModeInterface(self.connection).get_dsp_mode(board, cpu, humanize)
        return mode

    def get_dsp_modes_for_board(self, board, humanize=True):
        """
        Get modes for all CPUs on a selected board

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0


        **Input parameters:**

        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                                                  |
        +================+======+==============================================================================================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13                                                                                   |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | humanize       | No   | determines output format: as a simple integer (``${False}``), or as a descriptive string (``${True}``)       |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${modes}=    Get DSP Modes For Board    0x13    humanize=${False}
            ->  [(19, 49, 9),
            (19, 50, 9),
            (19, 51, 9),
            (19, 52, 9),
            (19, 65, 10),
            ....
            (19, 129, 10),
            (19, 130, 10),
            (19, 131, 10),
            (19, 132, 10)]

        **Example:**

        .. code-block:: robotframework

            ${modes}=   Get DSP Modes For Board    0x13
            ->  [('0x13', '0x31', '[mode_09]NyquistCommonChannelDeviceNormal'),
            ('0x13', '0x32', '[mode_09]NyquistCommonChannelDeviceNormal'),
            ('0x13', '0x33', '[mode_09]NyquistCommonChannelDeviceNormal'),
            ('0x13', '0x34', '[mode_09]NyquistCommonChannelDeviceNormal'),
            ('0x13', '0x41', '[mode_10]NyquistDedicatedChannelDevice'),
            ...
            ('0x13', '0x83', '[mode_10]NyquistDedicatedChannelDevice'),
            ('0x13', '0x84', '[mode_10]NyquistDedicatedChannelDevice')]

        | **Return value:**
        | a list of tuples (board, cpu, mode)
        """
        board = intlify(board)[0]
        return DspModeInterface(self.connection).get_dsp_mode_for_board(board, humanize=humanize)

    def get_available_boards(self, as_hex=True):
        """
        Get a list of boards used by WCDMA

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** ---

        **Input parameters:**

        +----------------+------+-----------------------------------------------------------------+
        | Parameter name | Man. | Description                                                     |
        +================+======+=================================================================+
        | as_hex         | No   | determines the output format, ``${True}`` or ``${False}``       |
        +----------------+------+-----------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${available_boards}=     Get Available Boards
            ->  ['0x13']

        **Example:**

        .. code-block:: robotframework

            ${available_boards}=    Get Available Boards    as_hex=${False}
            ->  [19]

        | **Return value:**
        | a list of board IDs used by WCDMA
        """
        return ServiceInterface(self.connection).get_available_boards(as_hex)
